import React, { useState, useEffect } from 'react';
import { LayoutDashboard, ReceiptText, Upload, TrendingUp, TrendingDown, Wallet } from 'lucide-react';
import axios from 'axios';
import { 
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  BarChart, Bar, Legend, Cell, PieChart, Pie
} from 'recharts';

const API_BASE_URL = 'http://localhost:8000';

function App() {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [data, setData] = useState<any[]>([]);
  const [summary, setSummary] = useState({ total: 0, positive: 0, negative: 0 });

  useEffect(() => {
    // Basic fetch could go here if we had a list endpoint
  }, []);

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const formData = new FormData();
    formData.append('file', file);

    try {
      const response = await axios.post(`${API_BASE_URL}/api/upload`, formData);
      setData(response.data.preview);
      // Mock summary calculation for demo purposes
      const mockSummary = response.data.preview.reduce((acc: any, curr: any) => {
        if (curr.amount > 0) acc.positive += curr.amount;
        else acc.negative += curr.amount;
        acc.total += curr.amount;
        return acc;
      }, { total: 0, positive: 0, negative: 0 });
      setSummary(mockSummary);
    } catch (error) {
      console.error("Error uploading file", error);
    }
  };

  return (
    <div className="flex h-screen bg-slate-50 font-sans">
      {/* Sidebar */}
      <div className="w-64 bg-slate-900 text-white flex flex-col">
        <div className="p-6 text-2xl font-bold flex items-center gap-2 border-b border-slate-800">
          <Wallet className="text-emerald-400" />
          <span>MoneyMinder</span>
        </div>
        <nav className="flex-1 p-4 space-y-2">
          <button 
            onClick={() => setActiveTab('dashboard')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-colors ${activeTab === 'dashboard' ? 'bg-emerald-600' : 'hover:bg-slate-800'}`}
          >
            <LayoutDashboard size={20} />
            Dashboard
          </button>
          <button 
            onClick={() => setActiveTab('transactions')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-colors ${activeTab === 'transactions' ? 'bg-emerald-600' : 'hover:bg-slate-800'}`}
          >
            <ReceiptText size={20} />
            Transactions
          </button>
        </nav>
        <div className="p-4 border-t border-slate-800">
          <label className="flex items-center gap-3 px-4 py-3 bg-slate-800 rounded-lg cursor-pointer hover:bg-slate-700 transition-colors">
            <Upload size={20} className="text-emerald-400" />
            <span>Import Statement</span>
            <input type="file" className="hidden" onChange={handleFileUpload} accept=".xlsx,.xls,.csv" />
          </label>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 overflow-auto p-8">
        <header className="mb-8">
          <h1 className="text-3xl font-bold text-slate-800">
            {activeTab === 'dashboard' ? 'Financial Overview' : 'Transaction History'}
          </h1>
          <p className="text-slate-500">Welcome back, here is what's happening with your money.</p>
        </header>

        {activeTab === 'dashboard' ? (
          <div className="space-y-8">
            {/* KPI Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                <div className="flex items-center justify-between mb-4">
                  <span className="text-slate-500 font-medium">Net Balance</span>
                  <div className="bg-emerald-100 p-2 rounded-lg"><Wallet className="text-emerald-600" size={20} /></div>
                </div>
                <div className="text-3xl font-bold">€{summary.total.toLocaleString()}</div>
              </div>
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                <div className="flex items-center justify-between mb-4">
                  <span className="text-slate-500 font-medium">Income</span>
                  <div className="bg-blue-100 p-2 rounded-lg"><TrendingUp className="text-blue-600" size={20} /></div>
                </div>
                <div className="text-3xl font-bold text-blue-600">€{summary.positive.toLocaleString()}</div>
              </div>
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                <div className="flex items-center justify-between mb-4">
                  <span className="text-slate-500 font-medium">Expenses</span>
                  <div className="bg-rose-100 p-2 rounded-lg"><TrendingDown className="text-rose-600" size={20} /></div>
                </div>
                <div className="text-3xl font-bold text-rose-600">€{Math.abs(summary.negative).toLocaleString()}</div>
              </div>
            </div>

            {/* Charts Section */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 h-96">
                <h3 className="text-lg font-bold mb-6">Spending Trend</h3>
                <ResponsiveContainer width="100%" height="100%">
                  <LineChart data={data}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" vertical={false} />
                    <XAxis dataKey="date" hide />
                    <YAxis stroke="#94a3b8" fontSize={12} tickFormatter={(val) => `€${val}`} />
                    <Tooltip 
                      contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                    />
                    <Line type="monotone" dataKey="amount" stroke="#10b981" strokeWidth={3} dot={false} />
                  </LineChart>
                </ResponsiveContainer>
              </div>
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
                <h3 className="text-lg font-bold mb-6">Category Breakdown</h3>
                <div className="h-72 flex items-center justify-center">
                   <p className="text-slate-400 italic">Upload a statement to see categorization breakdown.</p>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-slate-50 border-b border-slate-100">
                <tr>
                  <th className="px-6 py-4 font-semibold text-slate-700">Date</th>
                  <th className="px-6 py-4 font-semibold text-slate-700">Operation</th>
                  <th className="px-6 py-4 font-semibold text-slate-700">Category</th>
                  <th className="px-6 py-4 font-semibold text-slate-700 text-right">Amount</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {data.length > 0 ? data.map((item, idx) => (
                  <tr key={idx} className="hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4 text-slate-600">{new Date(item.date).toLocaleDateString()}</td>
                    <td className="px-6 py-4 font-medium">{item.operation}</td>
                    <td className="px-6 py-4">
                      <span className="bg-slate-100 text-slate-600 px-3 py-1 rounded-full text-sm">
                        {item.bank_category}
                      </span>
                    </td>
                    <td className={`px-6 py-4 text-right font-bold ${item.amount > 0 ? 'text-emerald-600' : 'text-rose-600'}`}>
                      {item.amount > 0 ? '+' : ''}{item.amount.toLocaleString()}€
                    </td>
                  </tr>
                )) : (
                  <tr>
                    <td colSpan={4} className="px-6 py-12 text-center text-slate-400">
                      No data available. Please import a bank statement.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

export default App;

from abc import ABC, abstractmethod
import pandas as pd
from typing import List, Dict, Any

class BaseBankParser(ABC):
    """
    Abstract Base Class for all bank statement parsers.
    Ensures that every module returns data in the Universal Financial Format.
    """

    @property
    @abstractmethod
    def bank_name(self) -> str:
        pass

    @abstractmethod
    def parse(self, file_path: str) -> List[Dict[str, Any]]:
        """
        Parses the file and returns a list of dictionaries 
        matching the Transaction database model.
        """
        pass

    def standardize_dataframe(self, df: pd.DataFrame, mapping: Dict[str, str]) -> pd.DataFrame:
        """Helper to rename columns and ensure UFF (Universal Financial Format)."""
        return df.rename(columns=mapping)

from typing import Dict, Type
from .base import BaseBankParser
from .sanpaolo import SanPaoloParser

class ParserFactory:
    """
    Factory to manage different bank parsers.
    Add new bank modules here.
    """
    _parsers: Dict[str, Type[BaseBankParser]] = {
        "sanpaolo": SanPaoloParser,
        # "revolut": RevolutParser, <-- Adding new banks is this easy
    }

    @classmethod
    def get_parser(cls, bank_name: str) -> BaseBankParser:
        parser_class = cls._parsers.get(bank_name.lower())
        if not parser_class:
            raise ValueError(f"No parser implemented for bank: {bank_name}")
        return parser_class()

