import pandas as pd
from typing import List, Dict, Any

class StatsService:
    def __init__(self, transactions: List[Dict[str, Any]]):
        self.df = pd.DataFrame(transactions)
        if not self.df.empty:
            self.df['date'] = pd.to_datetime(self.df['date'])

    def get_monthly_summary(self) -> List[Dict[str, Any]]:
        """
        Aggregates Income and Spend by month.
        """
        if self.df.empty:
            return []

        # Create a YYYY-MM period column
        self.df['month'] = self.df['date'].dt.strftime('%Y-%m')

        summary = self.df.groupby('month').apply(
            lambda x: pd.Series({
                'income': x[x['amount'] > 0]['amount'].sum(),
                'spend': abs(x[x['amount'] < 0]['amount'].sum())
            })
        ).reset_index()

        return summary.to_dict(orient='records')

    def get_category_breakdown(self) -> List[Dict[str, Any]]:
        """
        Aggregates spending by category.
        """
        if self.df.empty:
            return []

        # Filter only expenses
        expenses = self.df[self.df['amount'] < 0]

        breakdown = expenses.groupby('category')['amount'].sum().abs().reset_index()
        breakdown = breakdown.sort_values('amount', ascending=False)

        return breakdown.to_dict(orient='records')

    def get_kpi(self) -> Dict[str, float]:
        """
        Calculates Total Balance, Total Income, Total Expense.
        """
        if self.df.empty:
            return {"total_balance": 0, "total_income": 0, "total_expense": 0}

        return {
            "total_balance": self.df['amount'].sum(),
            "total_income": self.df[self.df['amount'] > 0]['amount'].sum(),
            "total_expense": self.df[self.df['amount'] < 0]['amount'].sum()
        }

from fastapi import APIRouter, Depends, HTTPException
from sqlalchemy.orm import Session
from app.core.database import get_db
from app.models.transaction import Transaction
from app.services.analytics.forecasting import ForecastingService
from app.services.analytics.stats import StatsService
from app.services.analytics.categorization import CategorizationService

router = APIRouter(prefix="/api/analytics", tags=["analytics"])

@router.get("/forecast")
async def get_forecast(days: int = 30, db: Session = Depends(get_db)):
    transactions = db.query(Transaction).all()
    if not transactions:
        return {"error": "No transactions found"}

    # Convert ORM objects to dicts
    data = [{"date": t.date, "amount": t.amount} for t in transactions]

    forecaster = ForecastingService(data)
    return forecaster.generate_forecast(days)

@router.get("/summary")
async def get_summary(db: Session = Depends(get_db)):
    transactions = db.query(Transaction).all()
    if not transactions:
        return {}

    data = [{"date": t.date, "amount": t.amount, "category": t.category} for t in transactions]

    stats = StatsService(data)
    return {
        "monthly": stats.get_monthly_summary(),
        "categories": stats.get_category_breakdown(),
        "kpi": stats.get_kpi()
    }

@router.post("/auto-categorize")
async def auto_categorize(db: Session = Depends(get_db)):
    # 1. Fetch all transactions
    all_tx = db.query(Transaction).all()

    # 2. Separate into labeled (training) and Uncategorized (to predict)
    labeled = [
        {"operation": t.operation, "details": t.details, "category": t.category} 
        for t in all_tx if t.category != "Uncategorized"
    ]

    to_predict = [t for t in all_tx if t.category == "Uncategorized"]

    if not labeled or not to_predict:
        return {"message": "Not enough data to categorize"}

    # 3. Train Model
    service = CategorizationService()
    service.train(labeled)

    # 4. Predict
    prediction_data = [{"operation": t.operation, "details": t.details} for t in to_predict]
    results = service.predict_categories(prediction_data)

    # 5. Update Database
    count = 0
    for tx_obj, res in zip(to_predict, results):
        if res['category'] != "Uncategorized":
            tx_obj.category = res['category']
            count += 1

    db.commit()
    return {"message": f"Successfully categorized {count} transactions"}

import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, FileText, PieChart as AnalyticsIcon, 
  Settings, Search, Bell, Briefcase, DollarSign,
  Landmark
} from 'lucide-react';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  BarChart as ReBarChart, Bar
} from 'recharts';
import axios from 'axios';

const API_BASE_URL = 'http://localhost:8000';

function App() {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [transactions, setTransactions] = useState<any[]>([]);
  const [salaries, setSalaries] = useState<any[]>([]);
  const [chartData, setChartData] = useState<any[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [kpi, setKpi] = useState({ netWorth: 0, income: 0, expense: 0 });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const [txRes, salRes, summaryRes] = await Promise.all([
        axios.get(`${API_BASE_URL}/api/transactions`),
        axios.get(`${API_BASE_URL}/api/salaries`),
        axios.get(`${API_BASE_URL}/api/analytics/summary`)
      ]);

      setTransactions(txRes.data);
      setSalaries(salRes.data);

      if (summaryRes.data) {
        setKpi({
            netWorth: summaryRes.data.kpi.total_balance,
            income: summaryRes.data.kpi.total_income,
            expense: summaryRes.data.kpi.total_expense
        });

        // Transform monthly summary for chart
        if (summaryRes.data.monthly) {
            const transformedChartData = summaryRes.data.monthly.map((m: any) => ({
                name: m.month,
                income: m.income,
                spend: m.spend
            }));
            setChartData(transformedChartData);
        }
      }

    } catch (error) {
      console.error("Error fetching data", error);
    }
  };

  const handleUpload = async (event: React.ChangeEvent<HTMLInputElement>, type: 'statement' | 'salary') => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    const formData = new FormData();
    formData.append('file', file);
    formData.append('doc_type', type);
    formData.append('source', 'sanpaolo'); 

    try {
      await axios.post(`${API_BASE_URL}/api/upload`, formData);
      await fetchData(); 
      alert(`${type === 'salary' ? 'Salary Slip' : 'Bank Statement'} uploaded successfully!`);
    } catch (error) {
      alert("Upload failed. Check console.");
      console.error(error);
    } finally {
      setIsUploading(false);
    }
  };

  return (
    <div className="flex h-screen overflow-hidden bg-canvas font-sans text-txt-primary">
      {/* Sidebar */}
      <aside className="w-72 bg-surface border-r border-slate-100 flex flex-col p-6">
        <div className="flex items-center gap-3 mb-12 px-2">
          <div className="glass-gradient p-2 rounded-xl">
            <AnalyticsIcon className="text-white" size={24} />
          </div>
          <span className="text-xl font-bold tracking-tight">MoneyMinder</span>
        </div>

        <nav className="space-y-2 flex-1">
          {[
            { id: 'dashboard', icon: LayoutDashboard, label: 'Analytics' },
            { id: 'documents', icon: FileText, label: 'Documents' },
            { id: 'settings', icon: Settings, label: 'Settings' },
          ].map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-4 px-4 py-3 rounded-2xl transition-all duration-200 ${
                activeTab === item.id 
                ? 'bg-activeTab text-primary-end font-semibold' 
                : 'text-txt-secondary hover:bg-slate-50'
              }`}
            >
              <item.icon size={22} className={activeTab === item.id ? 'text-primary-end' : 'text-txt-secondary'} />
              {item.label}
            </button>
          ))}
        </nav>

        <div className="mt-auto p-4 border-t border-slate-50">
          <p className="text-xs text-txt-secondary uppercase tracking-wider mb-4">Data Sources</p>
          <div className="space-y-3">
            <label className={`flex items-center gap-3 p-3 bg-slate-50 rounded-xl cursor-pointer hover:bg-slate-100 transition-colors ${isUploading ? 'opacity-50 pointer-events-none' : ''}`}>
              <Landmark size={18} className="text-primary-start" />
              <div className="flex-1">
                <p className="text-sm font-bold">Bank Statement</p>
                <p className="text-[10px] text-txt-secondary">CSV, Excel</p>
              </div>
