import pandas as pd
from typing import List, Dict, Any

class StatsService:
    def __init__(self, transactions: List[Dict[str, Any]]):
        self.df = pd.DataFrame(transactions)
        if not self.df.empty:
            self.df['date'] = pd.to_datetime(self.df['date'])

    def get_monthly_summary(self) -> List[Dict[str, Any]]:
        """
        Aggregates Income and Spend by month.
        Ensures strict YYYY-MM ordering and structure.
        """
        if self.df.empty:
            return []

        # Create a YYYY-MM period column
        self.df['month'] = self.df['date'].dt.strftime('%Y-%m')

        # Group by month and sum positive/negative amounts separately
        summary = self.df.groupby('month').apply(
            lambda x: pd.Series({
                'income': x.loc[x['amount'] > 0, 'amount'].sum(),
                'spend': abs(x.loc[x['amount'] < 0, 'amount'].sum())
            })
        ).reset_index()

        # Sort by month to ensure chart linearity
        summary = summary.sort_values('month')

        return summary.to_dict(orient='records')

    def get_category_breakdown(self) -> List[Dict[str, Any]]:
        """
        Aggregates spending by category.
        """
        if self.df.empty:
            return []

        # Filter only expenses
        expenses = self.df[self.df['amount'] < 0]

        if expenses.empty:
            return []

        breakdown = expenses.groupby('category')['amount'].sum().abs().reset_index()
        breakdown = breakdown.sort_values('amount', ascending=False)

        return breakdown.to_dict(orient='records')

    def get_kpi(self) -> Dict[str, float]:
        """
        Calculates Total Balance, Total Income, Total Expense.
        """
        if self.df.empty:
            return {"total_balance": 0, "total_income": 0, "total_expense": 0}

        return {
            "total_balance": self.df['amount'].sum(),
            "total_income": self.df.loc[self.df['amount'] > 0, 'amount'].sum(),
            "total_expense": self.df.loc[self.df['amount'] < 0, 'amount'].sum()
        }

