                'income': float(x.loc[x['amount'] > 0, 'amount'].sum()),
                'spend': float(abs(x.loc[x['amount'] < 0, 'amount'].sum()))
            }),
            include_groups=False
        ).reset_index()

        summary = summary.sort_values('month')

        # Standardize for JSON: replace NaN with None
        return summary.replace({np.nan: None}).to_dict(orient='records')

    def get_category_breakdown(self) -> List[Dict[str, Any]]:
