    fetchData();
    applyTheme(theme);
  }, [theme]);

  const applyTheme = (selectedTheme: 'lumina' | 'dark') => {
    const root = document.documentElement;
    const colors = themes[selectedTheme];
    Object.entries(colors).forEach(([key, value]) => {
      // Map camelCase to kebab-case variables
      const cssKey = key.replace(/([A-Z])/g, "-$1").toLowerCase();
      root.style.setProperty(`--${cssKey}`, value);
    });
    // Special handling for shadow which tailwind doesn't pick up automatically from root var nicely in some versions
    root.style.setProperty('--shadow-color', colors.shadow);
  };

  const fetchData = async () => {
    try {
      const [txRes, salRes, summaryRes] = await Promise.all([
        axios.get(`${API_BASE_URL}/api/transactions`),
        axios.get(`${API_BASE_URL}/api/salaries`),
        axios.get(`${API_BASE_URL}/api/analytics/summary`)
      ]);

      setTransactions(txRes.data);
      setSalaries(salRes.data);

      if (summaryRes.data && summaryRes.data.kpi) {
        setKpi({
            netWorth: summaryRes.data.kpi.total_balance,
            income: summaryRes.data.kpi.total_income,
            expense: summaryRes.data.kpi.total_expense
        });

        if (summaryRes.data.monthly) {
            const transformedChartData = summaryRes.data.monthly.map((m: any) => ({
                name: m.month,
                income: m.income,
                spend: m.spend,
                balance: m.balance
            }));
            setChartData(transformedChartData);
        }
      } else {
        // Reset if no data
        setKpi({ netWorth: 0, income: 0, expense: 0 });
        setChartData([]);
      }

    } catch (error) {
      console.error("Error fetching data", error);
    }
  };

  const handleUpload = async (event: React.ChangeEvent<HTMLInputElement>, type: 'statement' | 'salary') => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    const formData = new FormData();
    formData.append('file', file);
    formData.append('doc_type', type);
    formData.append('source', 'sanpaolo'); 

    try {
      await axios.post(`${API_BASE_URL}/api/upload`, formData);
      await fetchData(); 
      alert(`${type === 'salary' ? 'Salary Slip' : 'Bank Statement'} uploaded successfully!`);
    } catch (error) {
      alert("Upload failed. Check console.");
      console.error(error);
    } finally {
      setIsUploading(false);
    }
  };

  const handleFormatDatabase = async () => {
    if (!window.confirm("CRITICAL ACTION: This will permanently delete all transactions and salary slips. Are you sure?")) {
      return;
    }

    try {
      await axios.delete(`${API_BASE_URL}/api/system/reset`);
      await fetchData();
      alert("Database formatted successfully.");
    } catch (error) {
      alert("Format failed.");
      console.error(error);
    }
  };

  const renderDashboard = () => (
    <>
      <section className="grid grid-cols-1 md:grid-cols-3 gap-8 mb-10">
        <div className="bg-surface p-8 rounded-2xl shadow-soft">
          <p className="text-txt-secondary font-medium mb-2">Net Worth</p>
          <div className="flex items-end gap-3">
            <h2 className="text-4xl font-bold">€{kpi.netWorth.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})}</h2>
          </div>
        </div>
        <div className="bg-surface p-8 rounded-2xl shadow-soft">
          <p className="text-txt-secondary font-medium mb-2">Last Salary</p>
          <div className="flex items-end gap-3">
            <h2 className="text-4xl font-bold text-emerald-600">
              {salaries.length > 0 ? `€${salaries[0].net_income.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})}` : '€0.00'}
            </h2>
            <span className="mb-1 text-xs text-txt-secondary">{salaries.length > 0 ? salaries[0].month_reference : '-'}</span>
          </div>
        </div>
        <div className="bg-surface p-8 rounded-2xl shadow-soft flex items-center justify-between">
          <div>
            <p className="text-txt-secondary font-medium mb-2">Cash Flow (Total)</p>
            <div className="flex gap-4">
              <div>
                <p className="text-xs text-txt-secondary">In</p>
                <p className="text-lg font-bold text-emerald-600">€{kpi.income.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})}</p>
              </div>
              <div className="border-l border-slate-100 pl-4">
                <p className="text-xs text-txt-secondary">Out</p>
                <p className="text-lg font-bold text-rose-600">€{Math.abs(kpi.expense).toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})}</p>
              </div>
            </div>
          </div>
          <div className="h-16 w-24">
            <ResponsiveContainer width="100%" height="100%">
              <ReBarChart data={chartData.length > 0 ? chartData.slice(-4) : []}>
                <Bar dataKey="income" fill={theme === 'dark' ? '#FF8E53' : '#111315'} radius={[2, 2, 0, 0]} />
                <Bar dataKey="spend" fill="#FF8E53" radius={[2, 2, 0, 0]} />
              </ReBarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </section>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <section className="lg:col-span-2 bg-surface p-8 rounded-2xl shadow-soft h-[500px]">
          <h3 className="text-xl font-bold mb-8">Balance History</h3>
          <div className="h-[400px]">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData}>
                <defs>
                  <linearGradient id="colorBalance" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#FF8E53" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#FF8E53" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={theme === 'dark' ? '#2A2D31' : '#F4F6F8'} />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#6F767E', fontSize: 12}} dy={10} />
                <YAxis hide />
                <Tooltip 
                  contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 20px rgba(0,0,0,0.05)', padding: '12px', backgroundColor: themes[theme].bgSurface, color: themes[theme].textPrimary }}
                  formatter={(value: number) => [`€${value.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})}`, 'Balance']}
                />
                <Area type="monotone" dataKey="balance" stroke="#FF6B6B" strokeWidth={4} fillOpacity={1} fill="url(#colorBalance)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </section>

        <aside className="space-y-8">
          <div className="bg-surface p-6 rounded-2xl shadow-soft">
            <h3 className="font-bold text-lg mb-6 flex items-center gap-2">
              <Briefcase size={18} /> Income Sources
            </h3>
            <div className="space-y-4 max-h-64 overflow-y-auto">
              {salaries.length > 0 ? salaries.map((sal, idx) => (
                <div key={idx} className="flex items-center justify-between p-4 bg-canvas rounded-xl">
                  <div>
                    <p className="font-bold text-sm">{sal.employer}</p>
                    <p className="text-[10px] text-txt-secondary">{sal.month_reference}</p>
                  </div>
                  <span className="font-bold text-emerald-600">+€{sal.net_income.toLocaleString()}</span>
                </div>
              )) : <p className="text-center py-6 text-txt-secondary text-sm italic">No data.</p>}
            </div>
          </div>
        </aside>
      </div>
    </>
  );

  const renderSettings = () => (
    <div className="max-w-4xl space-y-8">
      {/* Theme Settings */}
      <section className="bg-surface p-8 rounded-2xl shadow-soft">
        <h3 className="text-xl font-bold mb-6 flex items-center gap-3">
          <Sun size={22} className="text-primary-start" /> Appearance
        </h3>
        <p className="text-txt-secondary mb-8">Personalize your Lumina experience with different themes.</p>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <button 
            onClick={() => setTheme('lumina')}
            className={`flex items-center justify-between p-6 rounded-2xl border-2 transition-all ${theme === 'lumina' ? 'border-primary-start bg-activeTab shadow-sm' : 'border-slate-100 hover:border-slate-200'}`}
          >
            <div className="flex items-center gap-4">
              <div className="w-10 h-10 glass-gradient rounded-xl flex items-center justify-center text-white"><Sun size={20} /></div>
              <div className="text-left">
                <p className="font-bold">Lumina Light</p>
                <p className="text-xs text-txt-secondary">Warm Orange & Silver</p>
              </div>
            </div>
            {theme === 'lumina' && <CheckCircle2 className="text-primary-start" />}
          </button>

          <button 
            onClick={() => setTheme('dark')}
            className={`flex items-center justify-between p-6 rounded-2xl border-2 transition-all ${theme === 'dark' ? 'border-primary-start bg-slate-800 shadow-sm' : 'border-slate-100 hover:border-slate-200'}`}
          >
            <div className="flex items-center gap-4">
              <div className="w-10 h-10 bg-slate-900 rounded-xl flex items-center justify-center text-primary-start"><Moon size={20} /></div>
              <div className="text-left">
                <p className="font-bold">Midnight Dark</p>
                <p className="text-xs text-txt-secondary">Deep Charcoal & Orange</p>
              </div>
            </div>
            {theme === 'dark' && <CheckCircle2 className="text-primary-start" />}
          </button>
        </div>
      </section>

      {/* Database Settings */}
      <section className="bg-surface p-8 rounded-2xl shadow-soft">
        <h3 className="text-xl font-bold mb-6 flex items-center gap-3 text-rose-600">
          <ShieldAlert size={22} /> Danger Zone
        </h3>
        <p className="text-txt-secondary mb-8">Management actions for your local data. These actions are irreversible.</p>

        <div className="p-6 bg-rose-50 rounded-2xl border border-rose-100 flex items-center justify-between">
          <div>
            <p className="font-bold text-rose-900">Format Database</p>
            <p className="text-sm text-rose-700">Clear all transactions, salary records, and history.</p>
          </div>
          <button 
            onClick={handleFormatDatabase}
            className="flex items-center gap-2 bg-rose-600 hover:bg-rose-700 text-white px-6 py-3 rounded-xl font-bold shadow-lg transition-colors"
          >
            <Trash2 size={18} /> Clear Data
          </button>
        </div>
      </section>
    </div>
  );

  return (
    <div className="flex h-screen overflow-hidden bg-canvas font-sans text-txt-primary transition-colors duration-300">
      {/* Sidebar */}
      <aside className="w-72 bg-surface border-r border-slate-100 flex flex-col p-6 transition-colors duration-300">
        <div className="flex items-center gap-3 mb-12 px-2">
          <div className="glass-gradient p-2 rounded-xl">
            <AnalyticsIcon className="text-white" size={24} />
          </div>
          <span className="text-xl font-bold tracking-tight">MoneyMinder</span>
        </div>

        <nav className="space-y-2 flex-1">
          {[
            { id: 'dashboard', icon: LayoutDashboard, label: 'Analytics' },
            { id: 'documents', icon: FileText, label: 'Documents' },
            { id: 'settings', icon: SettingsIcon, label: 'Settings' },
          ].map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center gap-4 px-4 py-3 rounded-2xl transition-all duration-200 ${
                activeTab === item.id 
                ? 'bg-activeTab text-primary-end font-semibold' 
                : 'text-txt-secondary hover:bg-slate-50'
              }`}
            >
              <item.icon size={22} className={activeTab === item.id ? 'text-primary-end' : 'text-txt-secondary'} />
              {item.label}
            </button>
          ))}
        </nav>

        <div className="mt-auto p-4 border-t border-slate-50">
          <p className="text-xs text-txt-secondary uppercase tracking-wider mb-4">Data Sources</p>
          <div className="space-y-3">
            <label className={`flex items-center gap-3 p-3 bg-slate-50 rounded-xl cursor-pointer hover:bg-slate-100 transition-colors ${isUploading ? 'opacity-50 pointer-events-none' : ''}`}>
              <Landmark size={18} className="text-primary-start" />
              <div className="flex-1 text-left">
                <p className="text-sm font-bold">Bank Statement</p>
                <p className="text-[10px] text-txt-secondary">CSV, Excel</p>
              </div>
              <input type="file" className="hidden" onChange={(e) => handleUpload(e, 'statement')} accept=".csv,.xlsx,.xls" />
            </label>
            <label className={`flex items-center gap-3 p-3 bg-slate-50 rounded-xl cursor-pointer hover:bg-slate-100 transition-colors ${isUploading ? 'opacity-50 pointer-events-none' : ''}`}>
              <Briefcase size={18} className="text-emerald-600" />
              <div className="flex-1 text-left">
                <p className="text-sm font-bold">Salary Slip</p>
                <p className="text-[10px] text-txt-secondary">PDF, TXT</p>
              </div>
              <input type="file" className="hidden" onChange={(e) => handleUpload(e, 'salary')} accept=".pdf,.txt" />
            </label>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto p-10">
        <header className="flex items-center justify-between mb-10">
          <div>
            <h1 className="text-3xl font-bold">{activeTab === 'settings' ? 'Settings' : 'Financial Analytics'}</h1>
            <p className="text-txt-secondary mt-1">
              {activeTab === 'settings' ? 'Manage your preferences and data.' : 'Track your net worth and income streams.'}
            </p>
          </div>
          <div className="flex items-center gap-4">
            <div className="relative">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-txt-secondary" size={18} />
              <input 
                type="text" 
                placeholder="Search..." 
                className="bg-surface pl-12 pr-6 py-3 rounded-full shadow-soft focus:outline-none focus:ring-2 focus:ring-primary-start/20 w-64 transition-colors duration-300"
              />
            </div>
          </div>
        </header>

        {activeTab === 'dashboard' ? renderDashboard() : activeTab === 'settings' ? renderSettings() : null}

        {/* Movements shown if dashboard is active */}
        {activeTab === 'dashboard' && (
          <section className="mt-10">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-bold">Recent Movements</h3>
            </div>
            <div className="bg-surface rounded-2xl shadow-soft overflow-hidden transition-colors duration-300">
              {transactions.length > 0 ? transactions.slice(0, 10).map((tx, idx) => (
                <div key={idx} className="flex items-center justify-between p-6 hover:bg-slate-50 transition-colors border-b border-slate-50 last:border-0">
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 bg-canvas rounded-full flex items-center justify-center text-txt-secondary transition-colors duration-300">
                      <DollarSign size={18} />
                    </div>
                    <div>
                      <p className="font-bold text-txt-primary">{tx.operation}</p>
                      <p className="text-xs text-txt-secondary mt-0.5">{new Date(tx.date).toLocaleDateString()}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className={`font-bold ${tx.amount > 0 ? 'text-emerald-600' : 'text-txt-primary'}`}>
                      {tx.amount > 0 ? '+' : ''}{tx.amount.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})} €
                    </p>
                    <p className="text-xs text-txt-secondary mt-0.5">{tx.category}</p>
                  </div>
                </div>
              )) : (
                <div className="p-12 text-center text-txt-secondary italic">
                  No recent movements. Upload a data source to begin.
                </div>
              )}
            </div>
          </section>
        )}
      </main>
    </div>
  );
}

export default App;

