async def get_transactions(db: Session = Depends(get_db)):
    txs = db.query(Transaction).order_by(Transaction.date.desc()).all()
    # Convert ORM objects to dicts manually to ensure sanitize_data can see all fields
    data = []
    for tx in txs:
        tx_dict = {column.name: getattr(tx, column.name) for column in tx.__table__.columns}
        data.append(tx_dict)
    return sanitize_data(data)

@app.post("/api/transactions")
async def add_transaction(transaction: dict, db: Session = Depends(get_db)):
    try:
        new_tx = Transaction(**transaction)
        db.add(new_tx)
        db.commit()
        db.refresh(new_tx)
        return sanitize_data(new_tx)
    except Exception as e:
        db.rollback()
        raise HTTPException(status_code=400, detail=str(e))

@app.put("/api/transactions/{tx_id}")
async def update_transaction(tx_id: int, transaction: dict, db: Session = Depends(get_db)):
    db_tx = db.query(Transaction).filter(Transaction.id == tx_id).first()
    if not db_tx:
        raise HTTPException(status_code=404, detail="Transaction not found")

    for key, value in transaction.items():
        setattr(db_tx, key, value)

    try:
        db.commit()
        db.refresh(db_tx)
        return sanitize_data(db_tx)
    except Exception as e:
        db.rollback()
        raise HTTPException(status_code=400, detail=str(e))

@app.delete("/api/transactions/{tx_id}")
async def delete_transaction(tx_id: int, db: Session = Depends(get_db)):
    db_tx = db.query(Transaction).filter(Transaction.id == tx_id).first()
    if not db_tx:
        raise HTTPException(status_code=404, detail="Transaction not found")

    try:
        db.delete(db_tx)
        db.commit()
        return {"status": "success"}
    except Exception as e:
        db.rollback()
        raise HTTPException(status_code=400, detail=str(e))

