import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, FileText, PieChart as AnalyticsIcon, 
  Settings as SettingsIcon, Search, Bell, Briefcase, DollarSign,
  Landmark, Trash2, Moon, Sun, ShieldAlert, CheckCircle2,
  Edit2, Plus, X, Save
} from 'lucide-react';
import { 
  AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  BarChart as ReBarChart, Bar
} from 'recharts';
import axios from 'axios';
import { themes } from './theme/themeConfig';

const API_BASE_URL = 'http://localhost:8000';

function App() {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [theme, setTheme] = useState<'lumina' | 'dark'>('lumina');
  const [transactions, setTransactions] = useState<any[]>([]);
  const [salaries, setSalaries] = useState<any[]>([]);
  const [chartData, setChartData] = useState<any[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [kpi, setKpi] = useState({ netWorth: 0, income: 0, expense: 0 });
  const [editingTx, setEditingTx] = useState<any | null>(null);
  const [showModal, setShowModal] = useState(false);

  useEffect(() => {
    fetchData();
    applyTheme(theme);
  }, [theme]);

  const applyTheme = (selectedTheme: 'lumina' | 'dark') => {
    const root = document.documentElement;
    const colors = themes[selectedTheme];
    Object.entries(colors).forEach(([key, value]) => {
      const cssKey = key.replace(/([A-Z])/g, "-$1").toLowerCase();
      root.style.setProperty(`--${cssKey}`, value);
    });
    root.style.setProperty('--shadow-color', colors.shadow);
  };

  const fetchData = async () => {
    try {
      const [txRes, salRes, summaryRes] = await Promise.all([
        axios.get(`${API_BASE_URL}/api/transactions`),
        axios.get(`${API_BASE_URL}/api/salaries`),
        axios.get(`${API_BASE_URL}/api/analytics/summary`)
      ]);

      setTransactions(txRes.data);
      setSalaries(salRes.data);

      if (summaryRes.data && summaryRes.data.kpi) {
        setKpi({
            netWorth: summaryRes.data.kpi.total_balance,
            income: summaryRes.data.kpi.total_income,
            expense: summaryRes.data.kpi.total_expense
        });

        if (summaryRes.data.monthly) {
            const transformedChartData = summaryRes.data.monthly.map((m: any) => ({
                name: m.month,
                income: m.income,
                spend: m.spend,
                balance: m.balance
            }));
            setChartData(transformedChartData);
        }
      } else {
        setKpi({ netWorth: 0, income: 0, expense: 0 });
        setChartData([]);
      }

    } catch (error) {
      console.error("Error fetching data", error);
    }
  };

  const handleUpload = async (event: React.ChangeEvent<HTMLInputElement>, type: 'statement' | 'salary') => {
    const selectedFiles = event.target.files;
    if (!selectedFiles || selectedFiles.length === 0) return;

    setIsUploading(true);
    const formData = new FormData();
    for (let i = 0; i < selectedFiles.length; i++) {
      formData.append('files', selectedFiles[i]);
    }
    formData.append('doc_type', type);
    formData.append('source', 'sanpaolo'); 

    try {
      await axios.post(`${API_BASE_URL}/api/upload`, formData);
      await fetchData(); 
      alert(`${selectedFiles.length} ${type === 'salary' ? 'Salary Slip(s)' : 'Bank Statement(s)'} uploaded successfully!`);
    } catch (error) {
      alert("Upload failed. Check console.");
      console.error(error);
    } finally {
      setIsUploading(false);
      event.target.value = '';
    }
  };

  const handleFormatDatabase = async () => {
    if (!window.confirm("CRITICAL ACTION: This will permanently delete all transactions and salary slips. Are you sure?")) {
      return;
    }

    try {
      await axios.delete(`${API_BASE_URL}/api/system/reset`);
      await fetchData();
      alert("Database formatted successfully.");
    } catch (error) {
      alert("Format failed.");
      console.error(error);
    }
  };

  const handleDeleteTx = async (id: number) => {
    if (!window.confirm("Are you sure you want to delete this transaction?")) return;
    try {
      await axios.delete(`${API_BASE_URL}/api/transactions/${id}`);
      fetchData();
    } catch (error) {
      console.error(error);
