                    <div className="text-left"><p className="font-bold text-txt-primary">{tx.operation}</p><p className="text-xs text-txt-secondary mt-0.5">{new Date(tx.date).toLocaleDateString()}</p></div>
                  </div>
                  <div className="text-right">
                    <p className={`font-bold ${tx.amount > 0 ? 'text-emerald-600' : 'text-txt-primary'}`}>{tx.amount > 0 ? '+' : ''}{tx.amount.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})} €</p>
                    <p className="text-xs text-txt-secondary mt-0.5">{tx.category}</p>
                  </div>
                </div>
              )) : <div className="p-12 text-center text-txt-secondary italic">No recent movements.</div>}
            </div>
          </section>
        )}
      </main>

      {/* Transaction Modal */}
      {showModal && editingTx && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-surface w-full max-w-lg rounded-3xl shadow-2xl p-8 animate-in fade-in zoom-in duration-200">
            <div className="flex items-center justify-between mb-8">
              <h3 className="text-2xl font-bold">{editingTx.id ? 'Edit Transaction' : 'New Transaction'}</h3>
              <button onClick={() => setShowModal(false)} className="p-2 hover:bg-slate-100 rounded-full transition-colors"><X size={24} /></button>
            </div>
            <form onSubmit={handleSaveTx} className="space-y-6 text-left">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <label className="text-sm font-bold text-txt-secondary">Date</label>
                  <input type="date" value={editingTx.date} onChange={(e) => setEditingTx({...editingTx, date: e.target.value})} className="w-full bg-canvas border-none rounded-xl p-3 focus:ring-2 focus:ring-primary-start/20 outline-none" required />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-bold text-txt-secondary">Amount (€)</label>
                  <input type="number" step="0.01" value={editingTx.amount} onChange={(e) => setEditingTx({...editingTx, amount: parseFloat(e.target.value)})} className="w-full bg-canvas border-none rounded-xl p-3 focus:ring-2 focus:ring-primary-start/20 outline-none font-bold" required />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-sm font-bold text-txt-secondary">Operation</label>
                <input type="text" value={editingTx.operation} onChange={(e) => setEditingTx({...editingTx, operation: e.target.value})} className="w-full bg-canvas border-none rounded-xl p-3 focus:ring-2 focus:ring-primary-start/20 outline-none" placeholder="e.g. Salary, Rent..." required />
              </div>
              <div className="space-y-2">
                <label className="text-sm font-bold text-txt-secondary">Details</label>
                <textarea value={editingTx.details} onChange={(e) => setEditingTx({...editingTx, details: e.target.value})} className="w-full bg-canvas border-none rounded-xl p-3 focus:ring-2 focus:ring-primary-start/20 outline-none h-24 resize-none" placeholder="Optional description..." />
              </div>
              <div className="pt-4 flex gap-4">
                <button type="button" onClick={() => setShowModal(false)} className="flex-1 bg-slate-100 hover:bg-slate-200 text-txt-primary font-bold py-4 rounded-2xl transition-colors">Cancel</button>
                <button type="submit" className="flex-1 glass-gradient text-white font-bold py-4 rounded-2xl shadow-brand transition-transform hover:scale-[1.02] flex items-center justify-center gap-2"><Save size={20} /> Save Changes</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;

