@app.post("/api/system/deduplicate")
async def deduplicate_transactions(db: Session = Depends(get_db)):
    try:
        # Find duplicates by grouping identical fields
        from sqlalchemy import func

        # Subquery to identify the first ID of each unique group
        subq = db.query(
            func.min(Transaction.id)
        ).group_by(
            Transaction.date,
            Transaction.amount,
            Transaction.operation,
            Transaction.details,
            Transaction.account_id
        ).subquery()

        # Delete transactions NOT in the subquery
        deleted = db.query(Transaction).filter(Transaction.id.notin_(subq)).delete(synchronize_session=False)
        db.commit()

        return {"status": "success", "deleted_count": deleted}
    except Exception as e:
        db.rollback()
        raise HTTPException(status_code=500, detail=f"Deduplication failed: {str(e)}")

