@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');
@import "tailwindcss";

@theme {
  --color-primary-start: var(--primary-start);
  --color-primary-end: var(--primary-end);
  --color-canvas: var(--bg-canvas);
  --color-surface: var(--bg-surface);
  --color-activeTab: var(--bg-active);
  --color-txt-primary: var(--text-primary);
  --color-txt-secondary: var(--text-secondary);
  --color-accent: var(--accent);

  --radius-2xl: 20px;

  --shadow-soft: 0px 4px 20px rgba(0, 0, 0, 0.05);
  --shadow-brand: 0px 10px 20px var(--shadow-color);
}

:root {
  /* Default Lumina Values */
  --primary-start: #FF8E53;
  --primary-end: #FF6B6B;
  --bg-canvas: #F4F6F8;
  --bg-surface: #FFFFFF;
  --bg-active: #FFF0E6;
  --text-primary: #1A1D1F;
  --text-secondary: #6F767E;
  --accent: #111315;
  --shadow-color: rgba(255, 107, 107, 0.3);
}

body {
  font-family: 'Plus Jakarta Sans', sans-serif;
  @apply bg-canvas text-txt-primary transition-colors duration-300;
}

/* Custom Utilities */
.glass-gradient {
  background: linear-gradient(135deg, var(--primary-start) 0%, var(--primary-end) 100%);
}

.squircle {
  border-radius: 12px;
}
